#[test]
fn test_the_scripts_of_the_text_layer() {
    crate::testport::assert_eq(rp_script_of(65), 0, "A is Latin");
    crate::testport::assert_eq(rp_script_of(233), 0, "e acute is Latin");
    crate::testport::assert_eq(rp_script_of(215), -1, "the multiplication sign is no letter");
    crate::testport::assert_eq(rp_script_of(1103), 1, "Cyrillic");
    crate::testport::assert_eq(rp_script_of(945), 2, "Greek");
    crate::testport::assert_eq(rp_script_of(1575), 3, "Arabic");
    crate::testport::assert_eq(rp_script_of(1488), 4, "Hebrew");
    crate::testport::assert_eq(rp_script_of(2325), 5, "Devanagari");
    crate::testport::assert_eq(rp_script_of(20013), 6, "Han");
    crate::testport::assert_eq(rp_script_of(54620), 7, "Hangul");
    crate::testport::assert_eq(rp_script_of(12354), 8, "Hiragana");
    crate::testport::assert_eq(rp_script_of(3585), 9, "Thai");
    crate::testport::assert_eq(rp_script_of(48), -1, "a digit belongs to no script");
    crate::testport::assert_eq(rpt_field(0, &crate::testport::test_file("corpus/synth/pdf/script-hebrew.pdf")[..], 2, rp_scope_full(), 0, rp_f_scripts()) & 16, 16, "a Hebrew page asks for the Hebrew script");
    crate::testport::assert_eq(rpt_field(0, &crate::testport::test_file("corpus/synth/pdf/script-devanagari.pdf")[..], 2, rp_scope_full(), 0, rp_f_scripts()) & 32, 32, "a Devanagari page asks for it");
    crate::testport::assert_eq(rpt_field(0, &crate::testport::test_file("corpus/synth/pdf/h-plain.pdf")[..], 2, rp_scope_full(), 0, rp_f_scripts()) & 1, 1, "a Latin page asks for Latin");
}
